import asyncio
from fastapi import FastAPI
from starlette.responses import StreamingResponse
import io
from pydub import AudioSegment
import uvicorn

app = FastAPI()

async def play_mp3(mp3_data, queue):
    await asyncio.sleep(1)  # Cambiado de 10 a 1
    while True:
        for mp3_chunk in mp3_data:  # Eliminado el "_,"
            await queue.put(mp3_chunk)

async def play_silence(queue):
    silence = AudioSegment.silent(duration=1000)  # 1 segundo de silencio
    silence_io = io.BytesIO()
    silence.export(silence_io, format="mp3")
    silence_bytes = silence_io.getvalue()

    while True:
        await asyncio.sleep(1)
        await queue.put(silence_bytes)

async def stream_audio(queue):
    while True:
        chunk = await queue.get()
        yield chunk
        queue.task_done()
        await asyncio.sleep(0.01)  # Agregado un pequeño sleep

